SELECT pt.*, wo.work_order_name, wo.status AS work_order_status, wo.priority AS work_order_priority, m.name AS material_name, m.model AS material_model, m.standard AS material_standard, mc.name AS category_name, u.login_name AS worker_login_name, u.position AS worker_position, u.department AS worker_department, u.phonenum AS worker_phone, ws.skill_level, ws.skill_score, ws.efficiency_rate, ws.quality_rate AS worker_quality_rate, CASE WHEN pt.task_quantity > 0 THEN ROUND((pt.completed_quantity / pt.task_quantity) * 100, 2) ELSE 0 END AS completion_rate, CASE WHEN pt.completed_quantity > 0 THEN ROUND((pt.qualified_quantity / pt.completed_quantity) * 100, 2) ELSE 0 END AS qualification_rate, cu.username AS create_user_name, uu.username AS update_user_name, IFNULL(report_stats.report_count, 0) AS report_count, IFNULL(report_stats.total_reported_hours, 0) AS total_reported_hours, IFNULL(qi_stats.quality_check_count, 0) AS quality_check_count, IFNULL(qi_stats.average_quality_score, 0) AS average_quality_score, CASE WHEN pt.plan_end_time IS NOT NULL AND pt.plan_end_time < NOW() AND pt.status NOT IN ('COMPLETED', 'QUALITY_CHECKED') THEN 1 ELSE 0 END AS is_overdue, CASE WHEN pt.plan_end_time IS NOT NULL AND pt.plan_end_time < NOW() THEN DATEDIFF(NOW(), pt.plan_end_time) ELSE 0 END AS overdue_days FROM jsh_production_task pt LEFT JOIN jsh_production_work_order wo ON pt.work_order_id = wo.id AND IFNULL(wo.delete_flag, '0') != '1' LEFT JOIN jsh_material m ON pt.product_id = m.id AND IFNULL(m.delete_flag, '0') != '1' LEFT JOIN jsh_material_category mc ON m.category_id = mc.id AND IFNULL(mc.delete_flag, '0') != '1' LEFT JOIN jsh_user u ON pt.worker_id = u.id AND IFNULL(u.delete_flag, '0') != '1' LEFT JOIN jsh_worker_skill ws ON pt.worker_id = ws.worker_id AND ws.skill_type = pt.task_type AND IFNULL(ws.delete_flag, '0') != '1' LEFT JOIN jsh_user cu ON pt.create_user = cu.id AND IFNULL(cu.delete_flag, '0') != '1' LEFT JOIN jsh_user uu ON pt.update_user = uu.id AND IFNULL(uu.delete_flag, '0') != '1' LEFT JOIN ( SELECT task_id, COUNT(*) AS report_count, SUM(work_hours) AS total_reported_hours FROM jsh_production_report WHERE IFNULL(delete_flag, '0') != '1' GROUP BY task_id ) report_stats ON pt.id = report_stats.task_id LEFT JOIN ( SELECT task_id, COUNT(*) AS quality_check_count, AVG(overall_score) AS average_quality_score FROM jsh_quality_inspection WHERE IFNULL(delete_flag, '0') != '1' GROUP BY task_id ) qi_stats ON pt.id = qi_stats.task_id WHERE 1=1 AND IFNULL(pt.delete_flag, '0') != '1'
AND pt.task_number LIKE #{bindTaskNumber}
AND pt.task_name LIKE #{bindTaskName}
AND pt.work_order_number LIKE #{bindWorkOrderNumber}
AND pt.task_type = #{taskType}
AND pt.process_step LIKE #{bindProcessStep}
AND (pt.product_name LIKE #{bindProductName} OR m.name LIKE #{bindProductName})
AND pt.priority = #{priority}
AND pt.status = #{status}
AND pt.worker_name LIKE #{bindWorkerName}
AND pt.worker_specialty LIKE #{bindWorkerSpecialty}
AND pt.assign_time >= #{assignTime}
AND pt.plan_start_time >= #{planStartTime}
AND pt.plan_end_time <= #{planEndTime}
AND pt.tenant_id = #{tenantId}
ORDER BY pt.create_time DESC
LIMIT #{offset}, #{rows}

SELECT COUNT(*)
FROM jsh_production_task pt
LEFT JOIN jsh_material m ON pt.product_id = m.id AND IFNULL(m.delete_flag, '0') != '1'
WHERE 1=1
AND IFNULL(pt.delete_flag, '0') != '1'


